"""Airflow DAG files generated by dbimport.schedule.airflow_dags, compared with saved files.

The expected files in tests/fixtures/dags/ are generated, not written by
hand. After an intended change to DAG generation, regenerate them with
DBIMPORT_UPDATE_EXPECTED_DAGS=1 and review the diff.
"""

import json
import os
import re
from collections.abc import Callable
from pathlib import Path

import pytest
import sqlalchemy as sa

from dbimport.schedule import airflow_dags
from dbimport.settings import get_settings
from tests.clock import NOW, frozen_datetime
from tests.configdb import insert_row, set_driver_path

EXPECTED_DIR = Path(__file__).resolve().parents[1] / "fixtures" / "dags"
UPDATE_EXPECTED = os.environ.get("DBIMPORT_UPDATE_EXPECTED_DAGS") == "1"
DAG_NAME = "DBImport_test"

Setup = Callable[[sa.Connection], None]


def _add_connection(conn: sa.Connection) -> None:
    """JDBC connection test_mysql with a configured driver path.

    DAG generation leaves out tables whose connection cannot be looked up.
    """
    set_driver_path(conn, "MySQL")
    insert_row(
        conn,
        "jdbc_connections",
        dbalias="test_mysql",
        jdbc_url="jdbc:mysql://source.example:3306/sourcedb",
    )


def _add_tables(conn: sa.Connection, with_connection: bool = True) -> None:
    """One full and one incremental import table in Hive database testdb."""
    if with_connection:
        _add_connection(conn)
    common = {"hive_db": "testdb", "dbalias": "test_mysql", "source_schema": "src"}
    insert_row(
        conn,
        "import_tables",
        hive_table="orders",
        source_table="orders",
        import_phase_type="full",
        etl_phase_type="truncate_insert",
        **common,
    )
    insert_row(
        conn,
        "import_tables",
        hive_table="events",
        source_table="events",
        import_phase_type="incr",
        etl_phase_type="merge",
        incr_column="id",
        incr_mode="append",
        **common,
    )


def _add_dag(conn: sa.Connection, **extra: object) -> None:
    insert_row(
        conn,
        "airflow_import_dags",
        dag_name=DAG_NAME,
        filter_hive="testdb.*",
        schedule_interval="None",
        **extra,
    )


def _default_dag(conn: sa.Connection) -> None:
    _add_tables(conn)
    _add_dag(conn)


def _import_and_etl_separate(conn: sa.Connection) -> None:
    _add_tables(conn)
    _add_dag(conn, run_import_and_etl_separate=1)


def _finish_all_stage1_first(conn: sa.Connection) -> None:
    _add_tables(conn)
    _add_dag(conn, finish_all_stage1_first=1)


def _custom_tasks(conn: sa.Connection) -> None:
    _default_dag(conn)
    insert_row(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="before_main_01",
        task_type="shell script",
        placement="before main",
        task_config="/usr/bin/sleep 1",
    )
    insert_row(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="in_main_01",
        task_type="Hive SQL",
        placement="in main",
        # Task ids of import tables are the Hive table names.
        task_dependency_upstream="orders",
        task_config="select 1",
    )
    insert_row(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="after_main_01",
        task_type="Trigger DAG",
        placement="after main",
        task_config="other_dag",
    )


def _export_dag(conn: sa.Connection) -> None:
    """A full and an incremental export of connection test_mysql."""
    _add_connection(conn)
    for table, export_type in (("orders", "full"), ("events", "incr")):
        insert_row(
            conn,
            "export_tables",
            dbalias="test_mysql",
            target_schema="dbo",
            target_table=table,
            hive_db="testdb",
            hive_table=table,
            export_type=export_type,
        )
    insert_row(
        conn,
        "airflow_export_dags",
        dag_name=DAG_NAME,
        schedule_interval="None",
        filter_dbalias="test_mysql",
    )


def _add_other_dags(conn: sa.Connection) -> None:
    """DAGs to wait for: an import DAG at 01:00 and a custom DAG on cron."""
    insert_row(
        conn,
        "airflow_import_dags",
        dag_name="other_import",
        filter_hive="otherdb.*",
        schedule_interval="01:00",
    )
    insert_row(
        conn,
        "airflow_custom_dags",
        dag_name="other_cron",
        schedule_interval="0 1 * * *",
    )


def _custom_dag(conn: sa.Connection) -> None:
    """A custom DAG at 03:00 whose DAG Sensor tasks wait for another DAG
    and for a DAG that does not exist."""
    _add_other_dags(conn)
    insert_row(
        conn, "airflow_custom_dags", dag_name=DAG_NAME, schedule_interval="03:00"
    )
    insert_row(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="in_main_01",
        task_type="shell script",
        placement="in main",
        task_config="/usr/bin/sleep 1",
    )
    insert_row(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="wait_other",
        task_type="DAG Sensor",
        placement="before main",
        task_config="other_import",
    )
    insert_row(
        conn,
        "airflow_tasks",
        dag_name=DAG_NAME,
        task_name="wait_missing",
        task_type="DAG Sensor",
        placement="before main",
        task_config="missing_dag.some_task",
    )


def _dag_sensors(conn: sa.Connection) -> None:
    """An import DAG at 03:00 with sensors for a DAG at 01:00, a DAG on
    cron and a DAG that does not exist."""
    _add_tables(conn)
    _add_other_dags(conn)
    insert_row(
        conn,
        "airflow_import_dags",
        dag_name=DAG_NAME,
        filter_hive="testdb.*",
        schedule_interval="03:00",
    )
    for sensor, wait_for_dag, extra in (
        ("s_other", "other_import", {"wait_for_task": "stop", "timeout_minutes": 30}),
        ("s_cron", "other_cron", {}),
        ("s_missing", "missing_dag", {}),
    ):
        insert_row(
            conn,
            "airflow_dag_sensors",
            dag_name=DAG_NAME,
            sensor_name=sensor,
            wait_for_dag=wait_for_dag,
            **extra,
        )


SCENARIOS: dict[str, Setup] = {
    "default_import_dag": _default_dag,
    "import_and_etl_separate": _import_and_etl_separate,
    "finish_all_stage1_first": _finish_all_stage1_first,
    "custom_tasks": _custom_tasks,
    "export_dag": _export_dag,
    "custom_dag": _custom_dag,
    "dag_sensors": _dag_sensors,
}


def _undefined_task_references(dag_source: str) -> set[str]:
    """Names used in set_upstream/set_downstream that no task defines.

    compile() only checks syntax; Airflow would fail to load such a file.
    """
    used = set(re.findall(r"\.set_(?:up|down)stream\((\w+)\)", dag_source))
    defined = set(re.findall(r"(?m)^(\w+) = ", dag_source))
    return used - defined


def _generate(tmp_path: Path) -> str:
    airflow_dags.Initialize().generate_dag(name=DAG_NAME, dag_folder=str(tmp_path))
    return (tmp_path / f"{DAG_NAME}.py").read_text()


def _check_against_expected(name: str, generated: str) -> None:
    expected_file = EXPECTED_DIR / f"{name}.py.txt"
    if UPDATE_EXPECTED:
        expected_file.parent.mkdir(parents=True, exist_ok=True)
        expected_file.write_text(generated)
    assert generated == expected_file.read_text()


@pytest.mark.parametrize("name", sorted(SCENARIOS))
def test_generate_dag_writes_expected_file(
    clean_config_db: None, db_connection: sa.Connection, tmp_path: Path, name: str
) -> None:
    SCENARIOS[name](db_connection)

    generated = _generate(tmp_path)

    compile(generated, f"{DAG_NAME}.py", "exec")
    assert _undefined_task_references(generated) == set()
    _check_against_expected(name, generated)


def test_generate_dag_leaves_out_tables_whose_connection_is_missing(
    clean_config_db: None, db_connection: sa.Connection, tmp_path: Path
) -> None:
    _add_tables(db_connection, with_connection=False)
    _add_dag(db_connection)

    generated = _generate(tmp_path)

    assert "-t orders" not in generated
    assert "-t events" not in generated


def test_generate_dag_with_valid_time_zone_uses_that_time_zone(
    clean_config_db: None, db_connection: sa.Connection, tmp_path: Path
) -> None:
    _add_tables(db_connection)
    _add_dag(db_connection, timezone="Asia/Tokyo")

    generated = _generate(tmp_path)

    assert 'local_tz = pendulum.timezone("Asia/Tokyo")' in generated


def test_generate_dag_with_invalid_time_zone_warns_and_uses_default_time_zone(
    clean_config_db: None,
    db_connection: sa.Connection,
    tmp_path: Path,
    caplog: pytest.LogCaptureFixture,
) -> None:
    _add_tables(db_connection)
    _add_dag(db_connection, timezone="Not/AZone")

    generated = _generate(tmp_path)

    assert "Time zone value specified for DAG is not valid" in caplog.text
    assert generated == (EXPECTED_DIR / "default_import_dag.py.txt").read_text()


def test_generate_dag_in_aws_mwaa_mode_writes_expected_file(
    clean_config_db: None,
    db_connection: sa.Connection,
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setattr(get_settings().airflow, "airflow_mode", "aws_mwaa")
    _default_dag(db_connection)

    generated = _generate(tmp_path)

    compile(generated, f"{DAG_NAME}.py", "exec")
    assert _undefined_task_references(generated) == set()
    _check_against_expected("aws_mwaa", generated)


class _FakeSendStatistics:
    """Records the documents instead of posting them (an external service)."""

    def __init__(self) -> None:
        self.sent: list[dict[str, object]] = []

    def send_rest_data(self, data: str) -> int:
        self.sent.append(json.loads(data))
        return 200


def test_send_json_writes_the_time_in_utc_with_its_offset(
    clean_config_db: None,
    db_connection: sa.Connection,
    in_host_zone: None,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    db_connection.execute(
        sa.text(
            "UPDATE configuration SET valueInt = 1 WHERE configKey IN"
            " ('post_airflow_dag_operations', 'post_data_to_rest')"
        )
    )
    monkeypatch.setattr(airflow_dags, "datetime", frozen_datetime(NOW))
    dags = airflow_dags.Initialize()
    fake = _FakeSendStatistics()
    monkeypatch.setattr(dags, "send_statistics", fake)

    dags.send_json(DAG_NAME, "finished")

    assert fake.sent == [
        {
            "type": "airflow_dag",
            "status": "finished",
            "dag": DAG_NAME,
            "airflow_timestamp": "2026-06-01T10:00:00.000000+00:00",
        }
    ]
